<template>
  <div v-if="views.length" class="source-view-links" :class="{ open }">
    <button
      type="button"
      class="source-view-trigger"
      :aria-expanded="open.toString()"
      @click="open = !open"
    >
      <span class="source-view-label">
        <span class="source-view-star" aria-hidden="true">✦</span>
        Seen in {{ views.length }} {{ views.length === 1 ? 'View' : 'Views' }}
      </span>
      <span class="source-view-arrow" aria-hidden="true">›</span>
    </button>
    <transition name="source-views">
      <ul v-if="open" class="source-view-list">
        <li v-for="view in views" :key="view.id">
          <router-link :to="`/view/${view.id}`">
            <span>{{ view.title }}</span>
            <time :datetime="new Date(Number(view.created_at)).toISOString()">{{ formatDate(view.created_at) }}</time>
          </router-link>
        </li>
      </ul>
    </transition>
  </div>
</template>

<script>
import { listViewsBySource } from '../../utils/viewShareSite';

export default {
  name: 'SourceViewLinks',
  props: {
    sourceId: {
      type: String,
      required: true,
    },
    aliases: {
      type: Array,
      default: () => [],
    },
  },
  data() {
    return {
      open: false,
      views: [],
    };
  },
  watch: {
    sourceId: {
      immediate: true,
      handler() {
        this.loadViews();
      },
    },
  },
  methods: {
    formatDate(value) {
      const date = new Date(Number(value));
      if (Number.isNaN(date.getTime())) return '';
      return new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(date);
    },
    async loadViews() {
      if (!this.sourceId) {
        this.views = [];
        return;
      }
      try {
        const index = await listViewsBySource();
        const ids = [this.sourceId, ...this.aliases];
        const unique = new Map();
        for (const id of ids) {
          for (const view of index[id] || []) unique.set(view.id, view);
        }
        this.views = [...unique.values()].sort((a, b) => Number(b.created_at) - Number(a.created_at));
      } catch {
        this.views = [];
      }
    },
  },
};
</script>

